1	/* AutoSeguro — mock de design. Folha compartilhada por todas as telas.
2	   Paleta derivada da identidade da Namastex: roxo profundo, magenta e ciano. */
3	:root{
4	  --fundo:#16012F; --superficie:#1F0A40; --superficie-2:#2A1152; --borda:#3B2068;
5	  --texto:#F2ECFF; --texto-fraco:#B9A8D9; --texto-mais-fraco:#8B79B0;
6	  --magenta:#FF00FF; --ciano:#00FFFF; --azul:#198BF5;
7	  --ok:#3DDC97; --alerta:#FFC857; --falha:#FF5C7A;
8	  --r:14px; --mono:ui-monospace,"Cascadia Mono",Consolas,monospace;
9	  --lateral:248px;
10	}
11	*{box-sizing:border-box}
12	body{margin:0;background:var(--fundo);color:var(--texto);
13	     font:15px/1.5 system-ui,"Segoe UI",Roboto,sans-serif;
14	     background-image:radial-gradient(900px 500px at 15% -10%, rgba(255,0,255,.10), transparent 60%),
15	                      radial-gradient(800px 500px at 92% 0%, rgba(0,255,255,.07), transparent 55%);
16	     background-attachment:fixed}
17	a{color:var(--ciano)}
18	h1,h2,h3{letter-spacing:-.2px}
19	
20	/* ───────── casca: menu lateral + conteúdo ───────── */
21	.app{display:grid;grid-template-columns:var(--lateral) 1fr;min-height:100vh}
22	@media (max-width:860px){ .app{grid-template-columns:1fr} .lateral{position:static;height:auto} }
23	
24	.lateral{position:sticky;top:0;height:100vh;background:rgba(22,1,47,.72);
25	         border-right:1px solid var(--borda);padding:18px 14px;display:flex;flex-direction:column;gap:18px;
26	         backdrop-filter:blur(6px)}
27	.lateral .produto{display:flex;flex-direction:column;gap:3px;padding:4px 8px 0}
28	.lateral .produto b{font-size:19px;position:relative;display:inline-block}
29	.lateral .produto b::before,.lateral .produto b::after{content:attr(data-t);position:absolute;inset:0;z-index:-1}
30	.lateral .produto b::before{color:var(--magenta);transform:translate(-2px,1px)}
31	.lateral .produto b::after{color:var(--ciano);transform:translate(2px,-1px)}
32	.lateral .produto span{color:var(--texto-mais-fraco);font-size:11.5px}
33	
34	.menu{display:flex;flex-direction:column;gap:3px}
35	.menu .grupo{color:var(--texto-mais-fraco);font-size:10.5px;text-transform:uppercase;
36	             letter-spacing:.12em;padding:12px 10px 5px}
37	.menu a{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;
38	        color:var(--texto-fraco);text-decoration:none;font-size:14px;border:1px solid transparent}
39	.menu a:hover{background:var(--superficie);color:var(--texto)}
40	.menu a[aria-current="page"]{background:var(--superficie-2);color:var(--texto);
41	        border-color:var(--borda);box-shadow:inset 2px 0 0 var(--magenta)}
42	.menu a .ic{width:18px;text-align:center;opacity:.9}
43	.menu a .cont{margin-left:auto;font-family:var(--mono);font-size:11px;color:var(--texto-mais-fraco)}
44	
45	.selo{margin-top:auto;display:flex;align-items:center;gap:9px;background:rgba(255,255,255,.04);
46	      border:1px solid var(--borda);border-radius:12px;padding:9px 10px}
47	.selo img{height:18px;width:auto;display:block;flex:none}
48	.selo small{color:var(--texto-mais-fraco);font-size:10.5px;line-height:1.3}
49	
50	.conteudo{padding:24px 26px 60px;min-width:0}
51	.cabecalho{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;flex-wrap:wrap;margin-bottom:20px}
52	.cabecalho h1{margin:0 0 3px;font-size:23px}
53	.cabecalho p{margin:0;color:var(--texto-fraco);font-size:13.5px;max-width:70ch}
54	
55	/* ───────── blocos ───────── */
56	.painel{background:var(--superficie);border:1px solid var(--borda);border-radius:var(--r);overflow:hidden}
57	.painel > header{padding:12px 16px;border-bottom:1px solid var(--borda);
58	                 display:flex;align-items:center;justify-content:space-between;gap:12px}
59	.painel > header h2{margin:0;font-size:12.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--texto-fraco)}
60	.painel > header .aux{color:var(--texto-mais-fraco);font-size:11.5px;font-family:var(--mono)}
61	
62	.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(168px,1fr));gap:12px;margin-bottom:20px}
63	.kpi{background:var(--superficie);border:1px solid var(--borda);border-radius:var(--r);padding:13px 15px}
64	.kpi .rotulo{color:var(--texto-mais-fraco);font-size:11px;text-transform:uppercase;letter-spacing:.08em}
65	.kpi .valor{font-size:23px;font-weight:650;margin-top:4px;font-variant-numeric:tabular-nums}
66	.kpi .nota{color:var(--texto-fraco);font-size:11.5px;margin-top:2px}
67	.kpi.destaque{border-color:var(--ok)} .kpi.destaque .valor{color:var(--ok)}
68	.kpi.perigo .valor{color:var(--alerta)}
69	
70	.chip{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:2px 9px;
71	      font-size:11px;font-weight:600;border:1px solid transparent;white-space:nowrap}
72	.chip::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
73	.chip.ok,.chip.cotada{color:var(--ok);background:rgba(61,220,151,.12);border-color:rgba(61,220,151,.35)}
74	.chip.alerta,.chip.handoff{color:var(--alerta);background:rgba(255,200,87,.12);border-color:rgba(255,200,87,.35)}
75	.chip.falha{color:var(--falha);background:rgba(255,92,122,.12);border-color:rgba(255,92,122,.35)}
76	.chip.neutra,.chip.recusada{color:var(--texto-fraco);background:rgba(185,168,217,.1);border-color:rgba(185,168,217,.3)}
77	.chip.viva,.chip.andamento{color:var(--ciano);background:rgba(0,255,255,.1);border-color:rgba(0,255,255,.3)}
78	
79	table{width:100%;border-collapse:collapse;font-size:13.5px}
80	th{text-align:left;color:var(--texto-mais-fraco);font-size:11px;text-transform:uppercase;
81	   letter-spacing:.08em;font-weight:600;padding:10px 16px;border-bottom:1px solid var(--borda)}
82	td{padding:11px 16px;border-bottom:1px solid rgba(59,32,104,.55);vertical-align:top}
83	tr:last-child td{border-bottom:0}
84	tbody tr:hover{background:var(--superficie-2)}
85	td.mono,.mono{font-family:var(--mono);font-size:12.5px}
86	td.num{text-align:right;font-variant-numeric:tabular-nums;font-family:var(--mono)}
87	
88	.mascarado{color:var(--texto-fraco);border-bottom:1px dashed var(--texto-mais-fraco);cursor:help}
89	.nota-rodape{margin-top:22px;color:var(--texto-mais-fraco);font-size:12px;line-height:1.7;
90	             border-top:1px solid var(--borda);padding-top:13px}
91	.nota-rodape strong{color:var(--texto-fraco)}
92	.aviso{background:rgba(255,200,87,.09);border:1px solid rgba(255,200,87,.35);color:var(--alerta);
93	       border-radius:12px;padding:11px 14px;font-size:13px;margin-bottom:18px}
