1	<!doctype html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Base de conhecimento — fichas de objeção de preço</title>
7	<style>
8	  :root{--bg:#0f1420;--painel:#161d2e;--borda:#26314a;--texto:#e7ecf5;--sutil:#93a1bd;--acento:#4f8cff;--erro:#ff6b6b;--ok:#4fd18b}
9	  *{box-sizing:border-box}
10	  body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--texto)}
11	  header{padding:16px 24px;border-bottom:1px solid var(--borda);display:flex;justify-content:space-between;align-items:center}
12	  header h1{font-size:16px;margin:0;font-weight:600}
13	  header nav a{color:var(--sutil);text-decoration:none;font-size:13px;margin-left:16px}
14	  main{display:grid;grid-template-columns:260px 1fr;gap:0;min-height:calc(100vh - 57px)}
15	  aside{border-right:1px solid var(--borda);padding:16px}
16	  aside button.nova{width:100%;padding:8px;margin-bottom:12px;background:var(--acento);color:#fff;border:none;border-radius:6px;cursor:pointer}
17	  #lista{list-style:none;margin:0 0 24px;padding:0}
18	  #lista li{padding:8px 10px;border-radius:6px;cursor:pointer;color:var(--sutil);font-size:13px}
19	  #lista li:hover,#lista li.ativa{background:var(--painel);color:var(--texto)}
20	  #lista li .badge{font-size:11px;padding:1px 6px;border-radius:10px;margin-left:6px}
21	  .badge.rascunho{background:#3a3220;color:#e0b84f}
22	  .badge.publicado{background:#173a2a;color:var(--ok)}
23	  .config-comercial{border-top:1px solid var(--borda);padding-top:14px}
24	  .config-comercial h2{font-size:12px;color:var(--sutil);margin:0 0 8px;text-transform:uppercase;letter-spacing:.03em}
25	  .config-comercial label{display:flex;align-items:flex-start;gap:8px;font-size:12px;color:var(--texto);cursor:pointer}
26	  .config-comercial input[type=checkbox]{margin-top:2px;width:auto}
27	  #config-status{font-size:11px;color:var(--sutil);margin-top:6px;min-height:14px}
28	  section{padding:24px;max-width:720px}
29	  label{display:block;font-size:12px;color:var(--sutil);margin:14px 0 4px}
30	  input,textarea{width:100%;padding:8px;border-radius:6px;border:1px solid var(--borda);background:var(--painel);color:var(--texto);font-family:inherit;font-size:14px}
31	  textarea{min-height:70px;resize:vertical}
32	  .ajuda{font-size:11px;color:var(--sutil);margin-top:4px}
33	  .argumentos{display:flex;flex-direction:column;gap:6px}
34	  .argumentos label{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--texto);margin:0}
35	  .argumentos input{width:auto}
36	  .acoes{margin-top:20px;display:flex;gap:10px}
37	  button{font-size:14px;padding:9px 16px;border-radius:6px;border:1px solid var(--borda);background:var(--painel);color:var(--texto);cursor:pointer}
38	  button.primario{background:var(--acento);border-color:var(--acento);color:#fff}
39	  #mensagem{margin-top:14px;padding:10px 12px;border-radius:6px;font-size:13px;display:none}
40	  #mensagem.erro{display:block;background:#3a1c1c;color:var(--erro)}
41	  #mensagem.sucesso{display:block;background:#173a2a;color:var(--ok)}
42	</style>
43	</head>
44	<body>
45	<header>
46	  <h1>Base de conhecimento — objeções de preço</h1>
47	  <nav><a href="/painel/index.html">Painel</a></nav>
48	</header>
49	<main>
50	  <aside>
51	    <button class="nova" id="btn-nova">+ nova ficha</button>
52	    <ul id="lista"></ul>
53	    <div class="config-comercial">
54	      <h2>Configuração comercial</h2>
55	      <label>
56	        <input type="checkbox" id="config-encaminhar">
57	        Lead fora do padrão de aceitação: encaminhar para um corretor?
58	      </label>
59	      <div id="config-status"></div>
60	    </div>
61	  </aside>
62	  <section>
63	    <label>Id (usado no arquivo, minúsculas e hífen)</label>
64	    <input id="campo-id" placeholder="ex.: preco-alto">
65	
66	    <label>Nome da ficha</label>
67	    <input id="campo-nome" placeholder="Nome curto para identificar a objeção">
68	
69	    <label>Frases do lead (uma por linha)</label>
70	    <textarea id="campo-frases" placeholder="Uma frase por linha"></textarea>
71	
72	    <label>Resposta orientada</label>
73	    <textarea id="campo-resposta" placeholder="Escreva como a IA deve responder. Números só como marcador, ex.: {{franquia}}."></textarea>
74	    <p class="ajuda">Números só como marcador <code>{{...}}</code> — nunca digitados soltos. A publicação recusa dígito fora de marcador ou marcador desconhecido.</p>
75	
76	    <label>Argumentos permitidos</label>
77	    <div class="argumentos">
78	      <label><input type="checkbox" value="coberturas"> Coberturas do plano</label>
79	      <label><input type="checkbox" value="franquia_por_plano"> Franquia de cada plano</label>
80	      <label><input type="checkbox" value="carencia"> Carência</label>
81	      <label><input type="checkbox" value="comparacao_entre_planos"> Comparação entre planos</label>
82	    </div>
83	
84	    <label>Tentativas antes do corretor (1 a 5)</label>
85	    <input id="campo-tentativas" type="number" min="1" max="5" placeholder="">
86	
87	    <div class="acoes">
88	      <button id="btn-rascunho">Salvar rascunho</button>
89	      <button id="btn-publicar" class="primario">Publicar</button>
90	    </div>
91	    <div id="mensagem"></div>
92	  </section>
93	</main>
94	<script>
95	const lista = document.getElementById('lista');
96	const mensagem = document.getElementById('mensagem');
97	const campoArgumentos = document.querySelectorAll('.argumentos input[type=checkbox]');
98	const campos = {
99	  id: document.getElementById('campo-id'),
100	  nome: document.getElementById('campo-nome'),
101	  frases: document.getElementById('campo-frases'),
102	  resposta: document.getElementById('campo-resposta'),
103	  tentativas: document.getElementById('campo-tentativas'),
104	};
105	
106	function mostrar(texto, tipo) {
107	  mensagem.textContent = texto;
108	  mensagem.className = tipo;
109	}
110	
111	function limparFormulario() {
112	  campos.id.value = '';
113	  campos.id.disabled = false;
114	  campos.nome.value = '';
115	  campos.frases.value = '';
116	  campos.resposta.value = '';
117	  campoArgumentos.forEach(cb => { cb.checked = false; });
118	  campos.tentativas.value = '';
119	  mensagem.className = '';
120	}
121	
122	function preencherFormulario(ficha) {
123	  // Não mexe em `mensagem` aqui: `salvar()` chama esta função logo depois de mostrar o
124	  // resultado, e limpar a classe agora escondia "Publicado."/"Rascunho salvo." na hora que
125	  // deveria aparecer. Quem troca de ficha na lista limpa a mensagem explicitamente.
126	  campos.id.value = ficha.id;
127	  campos.id.disabled = true;
128	  campos.nome.value = ficha.nome || '';
129	  campos.frases.value = (ficha.frases_do_lead || []).join('\n');
130	  campos.resposta.value = ficha.resposta_orientada || '';
131	  const marcados = new Set(ficha.argumentos_permitidos || []);
132	  campoArgumentos.forEach(cb => { cb.checked = marcados.has(cb.value); });
133	  // tentativas_antes_do_corretor ausente/null fica vazio -- nunca um número fabricado (LEI 2).
134	  campos.tentativas.value = ficha.tentativas_antes_do_corretor ?? '';
135	}
136	
137	async function carregarLista() {
138	  const resposta = await fetch('/api/objecoes');
139	  const fichas = await resposta.json();
140	  lista.innerHTML = '';
141	  for (const ficha of fichas) {
142	    const item = document.createElement('li');
143	    item.textContent = ficha.nome || ficha.id;
144	    const selo = document.createElement('span');
145	    selo.className = 'badge ' + ficha.status;
146	    selo.textContent = ficha.status;
147	    item.appendChild(selo);
148	    item.addEventListener('click', () => {
149	      mensagem.className = '';
150	      preencherFormulario(ficha);
151	    });
152	    lista.appendChild(item);
153	  }
154	}
155	
156	async function salvar(status) {
157	  const dados = {
158	    id: campos.id.value.trim(),
159	    nome: campos.nome.value,
160	    frases_do_lead: campos.frases.value.split('\n').map(l => l.trim()).filter(Boolean),
161	    resposta_orientada: campos.resposta.value,
162	    argumentos_permitidos: Array.from(campoArgumentos).filter(cb => cb.checked).map(cb => cb.value),
163	    tentativas_antes_do_corretor: campos.tentativas.value === '' ? null : Number(campos.tentativas.value),
164	    status: status,
165	  };
166	  if (!dados.id) {
167	    mostrar('Preencha o id da ficha.', 'erro');
168	    return;
169	  }
170	  const resposta = await fetch('/api/objecoes/' + encodeURIComponent(dados.id), {
171	    method: 'PUT',
172	    headers: { 'Content-Type': 'application/json' },
173	    body: JSON.stringify(dados),
174	  });
175	  const corpo = await resposta.json();
176	  if (!resposta.ok) {
177	    mostrar(corpo.erro || 'não foi possível salvar', 'erro');
178	    return;
179	  }
180	  mostrar(status === 'publicado' ? 'Publicado.' : 'Rascunho salvo.', 'sucesso');
181	  preencherFormulario(corpo);
182	  await carregarLista();
183	}
184	
185	async function carregarConfiguracaoComercial() {
186	  const resposta = await fetch('/api/configuracao-comercial');
187	  const corpo = await resposta.json();
188	  document.getElementById('config-encaminhar').checked = Boolean(corpo.encaminhar_lead_fora_do_padrao);
189	}
190	
191	async function salvarConfiguracaoComercial() {
192	  const status = document.getElementById('config-status');
193	  const marcado = document.getElementById('config-encaminhar').checked;
194	  const resposta = await fetch('/api/configuracao-comercial', {
195	    method: 'PUT',
196	    headers: { 'Content-Type': 'application/json' },
197	    body: JSON.stringify({ encaminhar_lead_fora_do_padrao: marcado }),
198	  });
199	  status.textContent = resposta.ok ? 'Salvo.' : 'Não foi possível salvar.';
200	}
201	
202	document.getElementById('btn-nova').addEventListener('click', limparFormulario);
203	document.getElementById('btn-rascunho').addEventListener('click', () => salvar('rascunho'));
204	document.getElementById('btn-publicar').addEventListener('click', () => salvar('publicado'));
205	document.getElementById('config-encaminhar').addEventListener('change', salvarConfiguracaoComercial);
206	
207	carregarLista();
208	carregarConfiguracaoComercial();
209	</script>
210	</body>
211	</html>
